import{_ as i,o as e,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-04-14","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-04-14","date":"2021-04-14T00:00:00.000Z","updated":"2021-04-17T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-04-14.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-04-14.md","lastUpdated":1780460162000}'),s={name:"posts/2021/Ceph_Crimson_SeaStore_2021-04-14.md"};function r(a,t,n,_,c,p){return e(),o("div",null,[...t[0]||(t[0]=[l('<p>本次会议主要讨论了Ceph存储系统中的watch和notify功能，以及如何优化这些机制以支持端到端映射。主要议题包括：</p><ul><li><strong>PR审查进展</strong>：上周提交了多个PR，主要涉及watch和notify功能的实现，包括分离watch的超时处理和一些小的修复。</li><li><strong>经典OSD与Crimson的watch和notify实现差异</strong>：讨论了经典OSD中watch与session紧密耦合的问题，以及在Crimson中如何实现更独立的watch机制。</li><li><strong>包管理优化</strong>：建议创建一个单独的包来区分Crimson和经典OSD，以避免混淆和提高用户识别度。</li><li><strong>调试信息输出</strong>：讨论了如何改进调试信息的输出格式，以便更方便地进行调试，特别是改进backtrace的输出。</li><li><strong>C-store性能优化</strong>：讨论了c-store的性能优化问题，包括改进缓存数据结构和事务处理的内部机制，以及增加性能计数器。</li></ul><p>会议决定的事项包括：</p><ul><li>继续审查和合并与watch和notify功能相关的PR。</li><li>决定是否可以移除经典OSD中watch和session的耦合，以简化实现并提高效率。</li><li>优化Crimson的包管理，创建一个单独的包来区分Crimson和经典OSD。</li><li>改进调试信息的输出格式，特别是backtrace的输出。</li><li>探索C-store的性能优化，包括改进缓存数据结构和事务处理的内部机制，以及增加性能计数器。</li></ul><p>后续行动计划包括：</p><ul><li>完成PR的审查和合并工作。</li><li>探索并实施移除经典OSD中watch和session耦合的方案。</li><li>优化Crimson的包管理，创建单独的包。</li><li>改进调试信息的输出格式，特别是backtrace的输出。</li><li>探索C-store的性能优化，包括改进缓存数据结构和事务处理的内部机制，以及增加性能计数器。</li></ul><h2 id="相关标签" tabindex="-1">相关标签 <a class="header-anchor" href="#相关标签" aria-label="Permalink to &quot;相关标签&quot;">​</a></h2><ul><li>[Ceph]</li><li>[分布式存储]</li><li>[CRUSH算法]</li><li>[高可用性]</li><li>[可伸缩性]</li></ul>',8)])])}const S=i(s,[["render",r]]);export{h as __pageData,S as default};
